export const SystemIconLibrary = {
  name: 'system',
  resolver: (name: keyof typeof Icons) => {
    if (name in Icons) {
      return `data:image/svg+xml,${encodeURIComponent(Icons[name])}`;
    }
    return '';
  }
};

export default SystemIconLibrary;
